var LS='yousef-plan-answers-v1';
var answers={}, touched={}, db=null, timers={}, inflight={}, TITLES={};
try{answers=JSON.parse(localStorage.getItem(LS)||'{}')||{}}catch(e){answers={}}
var total=0;
QG.forEach(function(g){g[1].forEach(function(q){total++; TITLES[q[0]]=q[1]})});

function isAnswered(id){var a=answers[id]; return !!(a&&((a.c&&a.c.length)||(a.t&&a.t.trim())))}
function updateMeter(){
  var n=0; Object.keys(TITLES).forEach(function(id){if(isAnswered(id)) n++});
  $('#meterTxt').textContent='الأسئلة المجاب عنها: '+n+' من '+total;
  $('#meterBar').style.width=Math.round(n/total*100)+'%';
  document.querySelectorAll('.q').forEach(function(c){c.classList.toggle('answered',isAnswered(c.getAttribute('data-id')))});
}
function setStatus(t){$('#saveStatus').textContent=t}

var idx=0;
$('#qWrap').innerHTML=QG.map(function(g){
  return '<div class="qgroup"><h3>'+esc(g[0])+'</h3>'+g[1].map(function(q){
    idx++;
    return '<div class="q" data-id="'+q[0]+'"><h3><small>'+idx+'</small>'+esc(q[1])+'</h3>'+
      (q[2]?'<p class="hint">'+esc(q[2])+'</p>':'')+
      (q[3].length?'<div class="chips">'+q[3].map(function(o){return '<button class="chip" data-o="'+esc(o)+'" aria-pressed="false">'+esc(o)+'</button>'}).join('')+'</div>':'')+
      '<textarea id="t-'+q[0]+'" placeholder="اكتب تصورك بحرية" aria-label="'+esc(q[1])+'"></textarea></div>';
  }).join('')+'</div>';
}).join('');

function applyAnswers(){
  Object.keys(TITLES).forEach(function(id){
    if(touched[id]) return;
    var a=answers[id]||{c:[],t:''}, card=$('.q[data-id="'+id+'"]');
    $('#t-'+id).value=a.t||'';
    card.querySelectorAll('.chip').forEach(function(c){c.setAttribute('aria-pressed',String((a.c||[]).indexOf(c.getAttribute('data-o'))>=0))});
  });
  updateMeter();
}
function persist(id){
  try{localStorage.setItem(LS,JSON.stringify(answers))}catch(e){}
  updateMeter();
  if(!db) return;
  clearTimeout(timers[id]);
  timers[id]=setTimeout(function(){flush(id)},700);
}
function flush(id){
  if(inflight[id]){timers[id]=setTimeout(function(){flush(id)},400); return}
  inflight[id]=true;
  var a=answers[id]||{c:[],t:''};
  db.doc('answers/'+id).set({q:TITLES[id],chips:a.c||[],text:a.t||'',updatedAt:Date.now()}).then(function(){
    setStatus('محفوظ على الخادم');
  }).catch(function(){
    setStatus('الحفظ في هذا المتصفح فقط');
  }).then(function(){inflight[id]=false});
}
$('#qWrap').addEventListener('click',function(e){
  var b=e.target.closest('.chip'); if(!b) return;
  var id=b.closest('.q').getAttribute('data-id'), o=b.getAttribute('data-o');
  var a=answers[id]=answers[id]||{c:[],t:''};
  var i=a.c.indexOf(o); if(i>=0) a.c.splice(i,1); else a.c.push(o);
  b.setAttribute('aria-pressed',String(i<0)); touched[id]=1; persist(id);
});
$('#qWrap').addEventListener('input',function(e){
  var t=e.target; if(t.tagName!=='TEXTAREA') return;
  var id=t.closest('.q').getAttribute('data-id');
  var a=answers[id]=answers[id]||{c:[],t:''};
  a.t=t.value; touched[id]=1; persist(id);
});
$('#copyAll').addEventListener('click',function(){
  var out=[];
  QG.forEach(function(g){g[1].forEach(function(q){
    var a=answers[q[0]]; if(!isAnswered(q[0])) return;
    out.push('## '+q[1]+'\n'+(a.c&&a.c.length?'الخيارات: '+a.c.join('، ')+'\n':'')+(a.t&&a.t.trim()?a.t.trim()+'\n':''));
  })});
  var text=out.length?out.join('\n'):'لا توجد إجابات بعد';
  var box=$('#exportBox'); box.value=text; box.classList.add('on'); box.style.minHeight='180px';
  function fallback(){box.focus(); box.select(); setStatus('حدد النص وانسخه يدوياً')}
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(function(){setStatus('تم النسخ')}).catch(fallback);
  } else fallback();
});
applyAnswers();

/* load from db when available */
if(window.claude&&window.claude.use){
  window.claude.use('db').then(function(d){
    if(!d) return;
    db=d;
    var timer=setTimeout(function(){setStatus('تعذر الوصول للخادم الآن، الحفظ في المتصفح')},10000);
    d.collection('answers').get().then(function(snap){
      clearTimeout(timer);
      snap.docs.forEach(function(doc){
        var v=doc.data(); if(!v||!TITLES[doc.id]||touched[doc.id]) return;
        answers[doc.id]={c:v.chips||[],t:v.text||''};
      });
      applyAnswers(); setStatus('محفوظ على الخادم');
    }).catch(function(){clearTimeout(timer); setStatus('الحفظ في هذا المتصفح فقط')});
  }).catch(function(){});
}

