    PF.filter(function(f){return f[1]===n}).forEach(function(f){
      html+='<details class="q"><summary>'+esc(f[2])+'</summary><p class="hint" style="margin-top:6px">'+esc(f[3])+'</p><textarea readonly style="min-height:200px;margin-top:8px" id="pf-'+f[0]+'">'+esc(buildPrompt(f))+'</textarea><div class="actions" style="margin-top:8px"><button class="btn" data-copy="pf-'+f[0]+'">نسخ</button></div></details>';
    });
