/* notes */
function noteCard(n){
  return '<article class="note-card" data-type="'+esc(n.type)+'">'+
    '<div class="meta"><span class="pill p-core">'+esc(typeLabel(n.type))+'</span><span>'+esc(secLabel(n.section))+'</span><time>'+esc(new Date(n.at).toLocaleString('ar'))+'</time></div>'+
    '<p>'+esc(n.text)+'</p>'+
    '<div class="row-actions"><button class="btn ghost mini" data-del-note="'+esc(n.id)+'">حذف</button></div>'+
  '</article>';
}
function renderNotes(){
  var wrap=document.getElementById('notesList');
  var count=document.getElementById('notesCount');
  if(!wrap) return;
  if(count) count.textContent=planNotes.length?planNotes.length+' ملاحظة':'لا ملاحظات بعد';
  var html='';
  NOTE_TYPES.forEach(function(t){
    var items=planNotes.filter(function(n){return n.type===t[0]}).sort(function(a,b){
      return (secRank(a.section)-secRank(b.section))||(a.at-b.at);
    });
    if(!items.length) return;
    html+='<div class="note-group"><h3>'+esc(t[1])+' ('+items.length+')</h3>'+items.map(noteCard).join('')+'</div>';
  });
  wrap.innerHTML=html||'<div class="empty">ابدأ بإضافة أول ملاحظة بالأعلى.</div>';
}
function buildNotesText(){
  var out=['ملاحظات التطبيق — '+new Date().toLocaleDateString('ar'),''];
  NOTE_TYPES.forEach(function(t){
    var items=planNotes.filter(function(n){return n.type===t[0]}).sort(function(a,b){
      return (secRank(a.section)-secRank(b.section))||(a.at-b.at);
    });
    if(!items.length) return;
    out.push('== '+t[1]+' ==');
    items.forEach(function(n){out.push('['+secLabel(n.section)+'] '+n.text)});
    out.push('');
  });
  return out.join('\n');
}
function copyBlock(text,statusEl,fallbackEl){
  function fallback(){
    if(fallbackEl){fallbackEl.value=text;fallbackEl.classList.add('on');fallbackEl.focus();fallbackEl.select()}
    if(statusEl) statusEl.textContent='حدد النص وانسخه يدوياً';
  }
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(function(){if(statusEl) statusEl.textContent='تم النسخ'}).catch(fallback);
  } else fallback();
}
var addNote=document.getElementById('addNote');
if(addNote){
  addNote.addEventListener('click',function(){
    var text=document.getElementById('noteText').value.trim();
    var st=document.getElementById('noteStatus');
    if(!text){if(st) st.textContent='اكتب الملاحظة أولاً'; return}
    planNotes.push({
      id:String(Date.now())+Math.random().toString(16).slice(2,7),
      type:document.getElementById('noteType').value,
      section:document.getElementById('noteSection').value,
      text:text,
      at:Date.now()
    });
    lsSet(NOTE_KEY,planNotes);
    document.getElementById('noteText').value='';
    if(st) st.textContent='أُضيفت الملاحظة';
    renderNotes();
  });
}
var copyNotes=document.getElementById('copyNotes');
if(copyNotes){
  copyNotes.addEventListener('click',function(){
    if(!planNotes.length){var st=document.getElementById('noteStatus'); if(st) st.textContent='لا ملاحظات بعد'; return}
    copyBlock(buildNotesText(),document.getElementById('noteStatus'),document.getElementById('notesFallback'));
  });
}
var notesList=document.getElementById('notesList');
if(notesList){
  notesList.addEventListener('click',function(e){
    var b=e.target.closest('[data-del-note]'); if(!b) return;
    var id=b.getAttribute('data-del-note');
    planNotes=planNotes.filter(function(n){return String(n.id)!==String(id)});
    lsSet(NOTE_KEY,planNotes);
    renderNotes();
  });
}

/* suggestions */
function suggestionCard(s){
  return '<article class="note-card" data-type="suggest">'+
    '<div class="meta"><span class="pill p-core">'+esc(secLabel(s.section))+'</span><time>'+esc(new Date(s.at).toLocaleString('ar'))+'</time></div>'+
    '<h3>'+esc(s.title)+'</h3>'+
    (s.text?'<p>'+esc(s.text)+'</p>':'')+
    '<div class="row-actions"><button class="btn ghost mini" data-del-sug="'+esc(s.id)+'">حذف</button></div>'+
  '</article>';
}
function renderSuggestions(){
  var wrap=document.getElementById('sugList');
  var count=document.getElementById('sugCount');
  if(!wrap) return;
  if(count) count.textContent=planSuggestions.length?planSuggestions.length+' اقتراح':'لا اقتراحات بعد';
  wrap.innerHTML=planSuggestions.length?planSuggestions.slice().sort(function(a,b){return b.at-a.at}).map(suggestionCard).join(''):'<div class="empty">أضف أول اقتراح بالأعلى.</div>';
}
function buildSuggestionsText(){
  var out=['اقتراحات لمميزات جديدة — '+new Date().toLocaleDateString('ar'),''];
  planSuggestions.slice().sort(function(a,b){return b.at-a.at}).forEach(function(s){
    out.push('['+secLabel(s.section)+'] '+s.title);
    if(s.text) out.push(s.text);
    out.push('');
  });
  return out.join('\n');
}
var addSug=document.getElementById('addSug');
if(addSug){
  addSug.addEventListener('click',function(){
    var title=document.getElementById('sugTitle').value.trim();
    var text=document.getElementById('sugText').value.trim();
    var st=document.getElementById('sugStatus');
    if(!title&&!text){if(st) st.textContent='اكتب الاسم أو الوصف أولاً'; return}
    planSuggestions.push({
      id:String(Date.now())+Math.random().toString(16).slice(2,7),
      title:title||'بدون اسم',
      text:text,
      section:document.getElementById('sugSection').value,
      at:Date.now()
    });
    lsSet(SUG_KEY,planSuggestions);
    document.getElementById('sugTitle').value='';
    document.getElementById('sugText').value='';
    if(st) st.textContent='أُضيف الاقتراح';
    renderSuggestions();
  });
}
var copySug=document.getElementById('copySug');
if(copySug){
  copySug.addEventListener('click',function(){
    if(!planSuggestions.length){var st=document.getElementById('sugStatus'); if(st) st.textContent='لا اقتراحات بعد'; return}
    copyBlock(buildSuggestionsText(),document.getElementById('sugStatus'),document.getElementById('sugFallback'));
  });
}
var sugList=document.getElementById('sugList');
if(sugList){
  sugList.addEventListener('click',function(e){
    var b=e.target.closest('[data-del-sug]'); if(!b) return;
    var id=b.getAttribute('data-del-sug');
    planSuggestions=planSuggestions.filter(function(s){return String(s.id)!==String(id)});
    lsSet(SUG_KEY,planSuggestions);
    renderSuggestions();
  });
}

renderChecklist();
renderPaid();
renderNotes();
renderSuggestions();
updateCheckProgress();



