var CMPL={done:'تم',part:'جزئي',miss:'ناقص',unk:'غير مؤكد'};
var CMPC={done:'p-core',part:'p-later',miss:'p-risk',unk:'p-extra'};
var cmpF='all';
function cmpRender(){
  var rows=CMP.filter(function(r){return cmpF==='all'||r[1]===cmpF});
  document.getElementById('cmpBody').innerHTML=rows.map(function(r){return '<tr><td>'+esc(r[0])+'</td><td><span class="pill '+CMPC[r[1]]+'">'+CMPL[r[1]]+'</span></td><td>'+esc(r[2])+'</td></tr>'}).join('');
  document.getElementById('cmpCount').textContent=rows.length+' من '+CMP.length;
  var n={done:0,part:0,miss:0,unk:0};CMP.forEach(function(r){n[r[1]]++});
  document.getElementById('cmpChips').innerHTML=[['all','الكل ('+CMP.length+')'],['done','تم ('+n.done+')'],['part','جزئي ('+n.part+')'],['miss','ناقص ('+n.miss+')'],['unk','غير مؤكد ('+n.unk+')']].map(function(c){return '<button class="chip" data-k="'+c[0]+'" aria-pressed="'+(cmpF===c[0])+'">'+c[1]+'</button>'}).join('');
  document.querySelectorAll('#cmpChips .chip').forEach(function(b){b.onclick=function(){cmpF=b.getAttribute('data-k');cmpRender()}});
}
cmpRender();
